def evaluateCalls(expr):
    stack = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isalpha():
            j = i
            while expr[j].isalpha():
                j += 1
            stack.append([expr[i:j], []])
            i = j + 1
        elif c == ',':
            i += 1
        elif c == ')':
            name, args = stack.pop()
            if name == "min":
                v = min(args)
            elif name == "max":
                v = max(args)
            else:
                v = sum(args)
            if not stack:
                return v
            stack[-1][1].append(v)
            i += 1
        else:
            j = i + 1
            while j < n and expr[j].isdigit():
                j += 1
            v = int(expr[i:j])
            if not stack:
                return v
            stack[-1][1].append(v)
            i = j
    return 0
